export function lookupGovernanceHeuristic(profileId: string): GovernanceHeuristicRow | null {
  return GOVERNANCE_HEURISTICS.find((row) => row.profileId === profileId) ?? null;
}

export function sliceGovernanceHeuristics(offset: number, size: number): readonly GovernanceHeuristicRow[] {
  const safeOffset = Number.isFinite(offset) ? Math.max(0, Math.trunc(offset)) : 0;
  const safeSize = Number.isFinite(size) ? Math.max(1, Math.trunc(size)) : 50;
  return GOVERNANCE_HEURISTICS.slice(safeOffset, safeOffset + safeSize);
}
